const input = $json;
const mission_key = input.mission_key ? String(input.mission_key) : null;
const mission_id = input.mission_id ? String(input.mission_id) : null;
if (!mission_key && !mission_id) {
  throw new Error('DECISION_AGGREGATE_INVALID_INPUT: mission_key or mission_id is required');
}
return [{ json: { mission_key, mission_id } }];

const crypto = require('crypto');
const row = $json[0] || $json;
if (!row.mission_id) {
  throw new Error('DECISION_AGGREGATE_NOT_FOUND: mission not found');
}
const hash = crypto.createHash('sha256').update(String(row.decision_md || '')).digest('hex');
return [{ json: { ...row, decision_hash: hash } }];

