INSERT INTO governance.decisions (mission_id, decision, decision_hash, rationale, decided_by)
VALUES ({{$json.mission_id ? ''' + $json.mission_id + ''' : 'NULL'}}::uuid, '{{$json.outcome}}', '{{$json.decision_hash}}', {{$json.decision_md ? ''' + $json.decision_md.replace(/'/g, '\'\'') + ''' : 'NULL'}}, 'governance-hub')
RETURNING id;
